SELECT nav.fund_code ,nav.trade_date ,nav.unit_nav FROM rrs_fund_nav nav INNER JOIN rrs_fundinfo fi ON fi.fund_code = nav.fund_code AND fi.is_deleted = 0
nav.is_deleted = 0 AND nav.fund_code IN
#{fundCode}
AND nav.trade_date >= #{navDateStart} AND nav.trade_date <= #{navDateEnd}
ORDER BY nav.fund_code ASC ,nav.trade_date ASC ,nav.id ASC
